export const getGetReceiptUrl = (params: GetReceiptParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/storage/objects?${stringifiedParams}` : `/api/storage/objects`
}

/**
 * @summary Serve a private receipt to an authorized administrator
 */
export const getReceipt = async (params: GetReceiptParams, options?: Parameters<typeof customFetch>[1]): Promise<Blob> => {

  return customFetch<Blob>(getGetReceiptUrl(params),
  {
    ...options,
    method: 'GET'


  }
);}





